-- STEP 1 of moving meditations and guides into the database (programs already live there).
-- Additive only: nothing that exists is changed or dropped, and the app does not read any of this yet.
-- Run ONCE in the Supabase SQL editor. The next file, materials-seed.sql, fills it with the two
-- materials that exist today (generated by `npm run build:materials-seed`).
--
-- Identity: every material keeps its human-readable id as `slug` (for example 'quick-grounding').
-- All the tables that already point at a meditation or a guide by that text id (sessions, positions,
-- check-ins, saved, reviews, reports, cart, cabinet) keep working with no data migration.
--
-- Who sees what:
--   * public.content      — as before: published and on sale for everyone, drafts for the author.
--   * *_meta tables       — what the catalog card needs (follows the visibility of the content row).
--   * *_body tables       — the material itself (audio file, guide text). Readable by the author, by anyone
--                           when the material is published and free, by a buyer, or by a person who added a
--                           free material to the cabinet. A paid material's body is NOT readable by the public.
-- NOTE for paid audio later: files in a public storage bucket can be opened by anyone who knows the link, so
-- paid audio must go to a private bucket with signed links. Free audio is fine as it is.

-- 1) readable id + length on the shared content table
alter table public.content add column if not exists slug text;
alter table public.content add column if not exists duration_minutes int;

alter table public.content drop constraint if exists content_slug_format;
alter table public.content add constraint content_slug_format
  check (slug is null or slug ~ '^[a-z0-9][a-z0-9-]{0,79}$');

-- one slug per kind (a program and a guide may not share one, but a null slug is allowed for old rows)
create unique index if not exists content_kind_slug_uidx on public.content (kind, slug) where slug is not null;

-- 2) MEDITATIONS ---------------------------------------------------------------------------------------------
create table if not exists public.content_meditation_meta (
  content_id uuid primary key references public.content (id) on delete cascade,
  -- how much of the recording is voice (kept for the transcript rule: voice-based ones need a transcript)
  format text not null default 'guided' check (format in ('guided', 'minimal', 'silent')),
  has_embedded_music boolean not null default false,
  offline_download_enabled boolean not null default false,
  background_sound_ids text[] not null default '{}',
  when_to_use text[] not null default '{}'
);

create table if not exists public.content_meditation_body (
  content_id uuid primary key references public.content (id) on delete cascade,
  audio_url text not null,
  -- author-written, author-confirmed text of the spoken practice (see utils/meditationTranscript.ts)
  transcript jsonb
);

-- 3) GUIDES --------------------------------------------------------------------------------------------------
create table if not exists public.content_guide_meta (
  content_id uuid primary key references public.content (id) on delete cascade,
  source text not null default 'uploaded_pdf' check (source in ('uploaded_pdf', 'sensoria_structured')),
  guide_type text,
  category text,
  tag text,
  pages int not null default 0,
  read_minutes int not null default 0,
  relevant_if text[] not null default '{}',
  outcomes text[] not null default '{}',
  outline jsonb,
  pdf_meta jsonb
);

create table if not exists public.content_guide_body (
  content_id uuid primary key references public.content (id) on delete cascade,
  -- an uploaded PDF (url) or the structured blocks of an interactive guide
  file_url text,
  blocks jsonb
);

-- 4) ACCESS ------------------------------------------------------------------------------------------------------
alter table public.content_meditation_meta enable row level security;
alter table public.content_meditation_body enable row level security;
alter table public.content_guide_meta enable row level security;
alter table public.content_guide_body enable row level security;

-- meta: exactly the visibility of the content row (a subquery on public.content applies that table's own policies)
drop policy if exists "meditation meta follows its content" on public.content_meditation_meta;
create policy "meditation meta follows its content" on public.content_meditation_meta
  for select using (exists (select 1 from public.content c where c.id = content_meditation_meta.content_id));

drop policy if exists "guide meta follows its content" on public.content_guide_meta;
create policy "guide meta follows its content" on public.content_guide_meta
  for select using (exists (select 1 from public.content c where c.id = content_guide_meta.content_id));

-- author writes (all four tables): only the author of the content row
drop policy if exists "authors manage their meditation meta" on public.content_meditation_meta;
create policy "authors manage their meditation meta" on public.content_meditation_meta
  for all
  using (exists (select 1 from public.content c where c.id = content_meditation_meta.content_id and c.author_id = auth.uid()))
  with check (exists (select 1 from public.content c where c.id = content_meditation_meta.content_id and c.author_id = auth.uid()));

drop policy if exists "authors manage their meditation body" on public.content_meditation_body;
create policy "authors manage their meditation body" on public.content_meditation_body
  for all
  using (exists (select 1 from public.content c where c.id = content_meditation_body.content_id and c.author_id = auth.uid()))
  with check (exists (select 1 from public.content c where c.id = content_meditation_body.content_id and c.author_id = auth.uid()));

drop policy if exists "authors manage their guide meta" on public.content_guide_meta;
create policy "authors manage their guide meta" on public.content_guide_meta
  for all
  using (exists (select 1 from public.content c where c.id = content_guide_meta.content_id and c.author_id = auth.uid()))
  with check (exists (select 1 from public.content c where c.id = content_guide_meta.content_id and c.author_id = auth.uid()));

drop policy if exists "authors manage their guide body" on public.content_guide_body;
create policy "authors manage their guide body" on public.content_guide_body
  for all
  using (exists (select 1 from public.content c where c.id = content_guide_body.content_id and c.author_id = auth.uid()))
  with check (exists (select 1 from public.content c where c.id = content_guide_body.content_id and c.author_id = auth.uid()));

-- body reads: published and free for everyone; a buyer; or someone who put the free material in their cabinet.
-- (the author's own read is covered by the "manage" policies above)
drop policy if exists "meditation body readable with access" on public.content_meditation_body;
create policy "meditation body readable with access" on public.content_meditation_body
  for select using (
    exists (
      select 1 from public.content c
      where c.id = content_meditation_body.content_id
        and ((c.status = 'published' and c.price = 0) or public.has_active_purchase(c.id))
    )
    or exists (
      select 1 from public.acquired_content a
      join public.content c on c.id = content_meditation_body.content_id
      where a.user_id = auth.uid() and a.kind = 'meditation' and a.content_id = c.id::text
    )
    or exists (
      select 1 from public.acquired_content a
      join public.content c on c.id = content_meditation_body.content_id
      where a.user_id = auth.uid() and a.kind = 'meditation' and a.content_id = c.slug
    )
  );

drop policy if exists "guide body readable with access" on public.content_guide_body;
create policy "guide body readable with access" on public.content_guide_body
  for select using (
    exists (
      select 1 from public.content c
      where c.id = content_guide_body.content_id
        and ((c.status = 'published' and c.price = 0) or public.has_active_purchase(c.id))
    )
    or exists (
      select 1 from public.acquired_content a
      join public.content c on c.id = content_guide_body.content_id
      where a.user_id = auth.uid() and a.kind = 'guide' and a.content_id = c.id::text
    )
    or exists (
      select 1 from public.acquired_content a
      join public.content c on c.id = content_guide_body.content_id
      where a.user_id = auth.uid() and a.kind = 'guide' and a.content_id = c.slug
    )
  );

-- 5) "Add free material to my cabinet" must recognise a material by its slug as well as by its uuid, because the
--    app (and every older table) refers to guides and meditations by slug. Same rule as before: the material's own
--    row must be published, of that kind, and cost 0. The short static list stays until the code stops using it.
drop policy if exists "people add free content to their own cabinet" on public.acquired_content;
create policy "people add free content to their own cabinet" on public.acquired_content
  for insert with check (
    auth.uid() = user_id
    and (
      exists (
        select 1 from public.content c
        where (c.id::text = acquired_content.content_id or c.slug = acquired_content.content_id)
          and c.kind = acquired_content.kind
          and c.status = 'published'
          and c.price = 0
      )
      or public.is_free_static_material(kind, content_id)
    )
  );

notify pgrst, 'reload schema';
